    typography: {
      type: Type.OBJECT,
      properties: {
        notes: { type: Type.ARRAY, items: { type: Type.STRING } },
        priority: { type: Type.STRING, enum: ["low", "medium", "high"] }
      },
      required: ["notes", "priority"]
    },
    layout_and_hierarchy: {
      type: Type.OBJECT,
      properties: {
        notes: { type: Type.ARRAY, items: { type: Type.STRING } },
        priority: { type: Type.STRING, enum: ["low", "medium", "high"] }
      },
      required: ["notes", "priority"]
    },
    balance_contrast_color: {
      type: Type.OBJECT,
      properties: {
        notes: { type: Type.ARRAY, items: { type: Type.STRING } },
        priority: { type: Type.STRING, enum: ["low", "medium", "high"] }
      },
      required: ["notes", "priority"]
    },
    style_and_story: {
      type: Type.OBJECT,
      properties: {
        notes: { type: Type.ARRAY, items: { type: Type.STRING } },
        priority: { type: Type.STRING, enum: ["low", "medium", "high"] }
      },
      required: ["notes", "priority"]
    },
    harmony: {
      type: Type.OBJECT,
      properties: {
        notes: { type: Type.ARRAY, items: { type: Type.STRING } },
        priority: { type: Type.STRING, enum: ["low", "medium", "high"] }
      },
      required: ["notes", "priority"]
    },
    modernity_and_trends: {
      type: Type.OBJECT,
      properties: {
        notes: { type: Type.ARRAY, items: { type: Type.STRING } },
        priority: { type: Type.STRING, enum: ["low", "medium", "high"] }
      },
      required: ["notes", "priority"]
    },
    actionable_suggestions: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    }
  },
  required: [
    "overall_summary",
    "legibility",
    "typography",
    "layout_and_hierarchy",
